/**
 * MatchScope Statistical Prediction Engine — "matchscope-statmodel-v1"
 *
 * A deterministic, transparent statistical model. No LLM calls, no external
 * prediction providers, no bookmaker odds — probabilities are generated by
 * MatchScope from real completed results ingested by the ESPN provider.
 *
 * Model:
 *  1. Elo ratings per team, updated from every completed match in the cached
 *     window (plus a persisted ratings store that accumulates over time).
 *  2. Win probabilities from the Elo difference with sport-specific home
 *     advantage; football adds a draw model; high-scoring sports are two-way.
 *  3. Football likely-score via a small Poisson grid around expected goals
 *     implied by the rating difference.
 *  4. Confidence derived from data coverage (how many tracked games each
 *     side has) and rating spread. Uncalibrated by design.
 */

const fs = require('fs');
const path = require('path');

const ENGINE_NAME = 'matchscope-statmodel-v1';
const BASE_ELO = 1500;
const K_FACTOR = 20;
const HOME_ADVANTAGE = {
  football: 55,
  basketball: 70,
  american_football: 45,
  ice_hockey: 55,
  baseball: 50
};
const TWO_WAY_SPORTS = new Set(['basketball', 'american_football', 'ice_hockey', 'baseball']);
const MAX_TRACKED_FORM = 8;

const DATA_DIR = process.env.MS_DATA_DIR || path.join(__dirname, '..', '..', 'data');
const RATINGS_FILE = path.join(DATA_DIR, 'ratings-store.json');

let store = null; // { appliedMatchIds: [], teamRatings: { "<sport>|<teamId>": { elo, games, form: [] } } }

function loadStore() {
  if (store) return store;
  try {
    if (fs.existsSync(RATINGS_FILE)) {
      const raw = JSON.parse(fs.readFileSync(RATINGS_FILE, 'utf8'));
      if (raw && typeof raw === 'object' && raw.teamRatings) {
        store = raw;
        return store;
      }
    }
  } catch (err) { /* fall through */ }
  store = { appliedMatchIds: [], teamRatings: {} };
  return store;
}

function persistStore() {
  try {
    if (!fs.existsSync(DATA_DIR)) fs.mkdirSync(DATA_DIR, { recursive: true });
    fs.writeFileSync(RATINGS_FILE, JSON.stringify(store));
  } catch (err) { /* best effort */ }
}

function teamKey(sport, teamId) {
  return `${sport}|${teamId}`;
}

function expectedScore(eloA, eloB) {
  return 1 / (1 + Math.pow(10, (eloB - eloA) / 400));
}

function marginMultiplier(scoreDiff, sport) {
  const abs = Math.abs(scoreDiff);
  if (TWO_WAY_SPORTS.has(sport)) {
    // ln-growth so blowouts matter but saturate.
    return Math.min(3, 1 + Math.log(1 + abs) / 2);
  }
  // Football: 1-goal margins mild, 3+ strong.
  return Math.min(2.5, 1 + abs * 0.3);
}

function formLetter(isHome, score) {
  const own = isHome ? score.home : score.away;
  const opp = isHome ? score.away : score.home;
  if (own > opp) return 'W';
  if (own === opp) return 'D';
  return 'L';
}

/**
 * Apply new completed matches (sorted oldest-first) to the persisted ratings
 * store. Idempotent by match id.
 */
function applyMatches(matches) {
  const s = loadStore();
  const applied = new Set(s.appliedMatchIds);
  const completed = matches
    .filter(m => m.status === 'completed' && m.score)
    .sort((a, b) => (a.start_time < b.start_time ? -1 : 1));

  let newCount = 0;
  for (const m of completed) {
    if (applied.has(m.id)) continue;
    const adv = HOME_ADVANTAGE[m.sport] || 50;
    const hk = teamKey(m.sport, m.home_team.id);
    const ak = teamKey(m.sport, m.away_team.id);
    if (!s.teamRatings[hk]) s.teamRatings[hk] = { elo: BASE_ELO, games: 0, form: [] };
    if (!s.teamRatings[ak]) s.teamRatings[ak] = { elo: BASE_ELO, games: 0, form: [] };

    const expHome = expectedScore(s.teamRatings[hk].elo + adv, s.teamRatings[ak].elo);
    const result = formLetter(true, m.score); // home perspective: W/D/L
    const actualHome = result === 'W' ? 1 : result === 'D' ? 0.5 : 0;
    const kEff = K_FACTOR * marginMultiplier(m.score.home - m.score.away, m.sport);

    s.teamRatings[hk].elo += kEff * (actualHome - expHome);
    s.teamRatings[ak].elo += kEff * ((1 - actualHome) - (1 - expHome));

    s.teamRatings[hk].games += 1;
    s.teamRatings[ak].games += 1;
    s.teamRatings[hk].form.unshift(formLetter(true, m.score));
    s.teamRatings[ak].form.unshift(formLetter(false, m.score));
    s.teamRatings[hk].form = s.teamRatings[hk].form.slice(0, MAX_TRACKED_FORM);
    s.teamRatings[ak].form = s.teamRatings[ak].form.slice(0, MAX_TRACKED_FORM);

    s.appliedMatchIds.push(m.id);
    applied.add(m.id);
    newCount += 1;
  }

  // Keep the applied-id list bounded (oldest dropped; those matches are older
  // than the cache window anyway and cannot be re-applied).
  if (s.appliedMatchIds.length > 5000) {
    s.appliedMatchIds = s.appliedMatchIds.slice(-3000);
  }

  if (newCount > 0) persistStore();
  return newCount;
}

function roundTo3(x) {
  return Math.round(x * 1000) / 1000;
}

function poissonPmf(lambda, k) {
  let fact = 1;
  for (let i = 2; i <= k; i++) fact *= i;
  return (Math.exp(-lambda) * Math.pow(lambda, k)) / fact;
}

function likelyScoreFootball(diff) {
  const xgHome = Math.min(3.6, Math.max(0.25, 1.30 + (diff / 400) * 1.1));
  const xgAway = Math.min(3.4, Math.max(0.25, 1.05 - (diff / 400) * 1.1));
  let best = { h: 1, a: 1, p: -1 };
  let over25 = 0;
  let totalMass = 0;
  for (let h = 0; h <= 6; h++) {
    for (let a = 0; a <= 6; a++) {
      const p = poissonPmf(xgHome, h) * poissonPmf(xgAway, a);
      totalMass += p;
      if (h + a >= 3) over25 += p;
      if (p > best.p) best = { h, a, p };
    }
  }
  return {
    likely_score: { home: best.h, away: best.a },
    expected_goals: { home: roundTo3(xgHome), away: roundTo3(xgAway) },
    over_2_5_goals: roundTo3(over25 / totalMass)
  };
}

function confidenceFor(homeGames, awayGames, diff) {
  const coverage = Math.min(homeGames, awayGames);
  const spread = Math.abs(diff);
  let level, score;
  if (coverage >= 5) {
    level = 'high';
    score = Math.min(92, 74 + Math.min(14, Math.round(spread / 25)) + Math.min(4, coverage - 5));
  } else if (coverage >= 2) {
    level = 'medium';
    score = 66 + Math.min(12, Math.round(spread / 30)) + coverage;
  } else {
    level = 'low';
    score = 52 + Math.min(10, Math.round(spread / 40));
  }
  return { level, score: Math.min(95, score) };
}

function h2hFromCache(matches, homeTeamId, awayTeamId) {
  const meetings = matches
    .filter(m =>
      m.status === 'completed' &&
      m.score &&
      ((m.home_team.id === homeTeamId && m.away_team.id === awayTeamId) ||
       (m.home_team.id === awayTeamId && m.away_team.id === homeTeamId))
    )
    .sort((a, b) => (a.start_time > b.start_time ? 1 : -1))
    .slice(-3)
    .reverse();
  return meetings.map(m => ({
    date: m.start_time,
    score: `${m.home_team.name} ${m.score.home} - ${m.score.away} ${m.away_team.name}`
  }));
}

/**
 * Generate the prediction for an upcoming match. Returns null when there is
 * not enough data to model it (unknown teams).
 */
function predict(match, allMatches) {
  if (!match || match.status === 'completed') return null;
  const s = loadStore();
  const hk = teamKey(match.sport, match.home_team.id);
  const ak = teamKey(match.sport, match.away_team.id);
  const home = s.teamRatings[hk];
  const away = s.teamRatings[ak];

  const adv = HOME_ADVANTAGE[match.sport] || 50;
  const homeElo = (home ? home.elo : BASE_ELO) + adv;
  const awayElo = away ? away.elo : BASE_ELO;
  const diff = homeElo - awayElo;
  const twoWay = TWO_WAY_SPORTS.has(match.sport);

  let pHome, pDraw, pAway;
  if (twoWay) {
    pHome = expectedScore(homeElo, awayElo);
    pDraw = 0;
    pAway = roundTo3(1 - pHome);
    pHome = roundTo3(pHome);
  } else {
    // Draw probability peaks when teams are even, decays with rating gap.
    pDraw = Math.min(0.34, Math.max(0.10, 0.34 * Math.exp(-Math.pow(diff / 210, 2))));
    const pHomeNoDraw = expectedScore(homeElo, awayElo);
    pHome = pHomeNoDraw * (1 - pDraw);
    pAway = (1 - pHomeNoDraw) * (1 - pDraw);
    pDraw = roundTo3(pDraw);
    pHome = roundTo3(pHome);
    pAway = roundTo3(pAway);
  }

  const homeGames = home ? home.games : 0;
  const awayGames = away ? away.games : 0;
  const conf = confidenceFor(homeGames, awayGames, diff);

  const factors = [];
  factors.push({
    factor: 'Elo rating edge',
    weight: diff > 60 ? 'home' : diff < -60 ? 'away' : 'neutral',
    description: `${match.home_team.name} ${Math.round(homeElo - adv)} vs ${match.away_team.name} ${Math.round(awayElo)} (home advantage +${adv} applied to the home side).`
  });
  if (home && home.form.length > 0) {
    const wins = home.form.filter(f => f === 'W').length;
    factors.push({
      factor: 'Home recent form',
      weight: wins >= 3 ? 'positive' : wins === 0 ? 'negative' : 'neutral',
      description: `${match.home_team.name} won ${wins} of their last ${home.form.length} tracked matches (${home.form.slice(0, 5).join(' ')}).`
    });
  }
  if (away && away.form.length > 0) {
    const wins = away.form.filter(f => f === 'W').length;
    factors.push({
      factor: 'Away recent form',
      weight: wins >= 3 ? 'positive' : wins === 0 ? 'negative' : 'neutral',
      description: `${match.away_team.name} won ${wins} of their last ${away.form.length} tracked matches (${away.form.slice(0, 5).join(' ')}).`
    });
  }
  const h2h = h2hFromCache(allMatches, match.home_team.id, match.away_team.id);
  if (h2h.length > 0) {
    factors.push({
      factor: 'Head-to-head (recent tracked meetings)',
      weight: 'neutral',
      description: h2h.map(x => x.score).join(' · ')
    });
  }

  const prediction = {
    match_id: match.id,
    sport: match.sport,
    match_summary: `${match.home_team.name} vs ${match.away_team.name} (${match.league})`,
    generated_at: new Date().toISOString(),
    engine: {
      name: ENGINE_NAME,
      version: '1.0.0',
      is_live_llm: false,
      calibrated: false
    },
    uncalibrated_probabilities: {
      home_win: pHome,
      draw: pDraw,
      away_win: pAway
    },
    uncertainty: {
      level: conf.level,
      uncalibrated_score: roundTo3(conf.score / 100),
      note: `Confidence from data coverage: ${homeGames} tracked home-team games, ${awayGames} tracked away-team games. Uncalibrated model output.`
    },
    reasoning_factors: factors,
    data_coverage: {
      home_team_games: homeGames,
      away_team_games: awayGames
    },
    team_ratings: {
      home: Math.round(homeElo - adv),
      away: Math.round(awayElo)
    },
    disclaimer: 'Probabilities generated by the MatchScope statistical engine from real ingested results. Uncalibrated, no win guarantees, no bookmaker odds, no betting advice.'
  };

  if (!twoWay) {
    Object.assign(prediction, likelyScoreFootball(diff));
  }

  return prediction;
}

/** Team form arrays (most recent first) for UI display. */
function getForm(match) {
  const s = loadStore();
  const home = s.teamRatings[teamKey(match.sport, match.home_team.id)];
  const away = s.teamRatings[teamKey(match.sport, match.away_team.id)];
  return {
    home: home ? home.form.slice(0, 5) : [],
    away: away ? away.form.slice(0, 5) : []
  };
}

module.exports = {
  ENGINE_NAME,
  BASE_ELO,
  applyMatches,
  predict,
  getForm,
  // exposed for tests
  _internals: { expectedScore, marginMultiplier, likelyScoreFootball, confidenceFor, poissonPmf, loadStore }
};
